const r3 = (n: number) => Math.round(n * 1000) / 1000;
/** ~9 km seaward of the beach point, so the marine model returns a sea cell. */
export function marinePoint(lat: number, lon: number, seaward: number) {
  const th = (seaward * Math.PI) / 180, d = 0.08;
  return {lat: r3(lat + d * Math.cos(th)), lon: r3(lon + (d * Math.sin(th)) / Math.cos((lat * Math.PI) / 180))};
}

export const coastSurfSpots: SurfSpot[] = COAST_ROWS.map(([id, name, region, type, , , seaward, timeZone, country]) => ({
  ...(timeZone ? {timeZone} : {}), ...(country ? {country} : {}), id, name, region, type, skill: 'Intermediate', idealDirection: seaward, exposure: 1, period: [9, 18], tides: ['Low', 'Rising'],
  seaward, character: 'Generic profile', hazards: null, illustrative: true, waveRange: [2, 8], windTolerance: 1, organizationPreference: 70,
}));

const common = {difficulty: null, orientation: null, idealSwell: null, periodRange: null, tidePreferences: null, faceRange: null, hazards: null, hazardsComplete: false, sources: [], checkedOn: '2026-10-29'} as const;
/** Great-circle km between the beach point and the marine query point (the note states the real distance: 9 km for the default point, more or less for an explicit sea point). */
const kmBetween = (aLat: number, aLon: number, bLat: number, bLon: number) => { const r = Math.PI / 180, h = Math.sin(((bLat - aLat) * r) / 2) ** 2 + Math.cos(aLat * r) * Math.cos(bLat * r) * Math.sin(((bLon - aLon) * r) / 2) ** 2; return 12742 * Math.asin(Math.sqrt(h)); };
const noteFor = (km: number, explicit: boolean) => `Approximate public map position for the beach; the marine point is ~${Math.round(km)} km ${explicit ? 'away, an explicit sea point (marinePoints.ts)' : 'seaward'}. Spot profile is a generic coastal default, not a surveyed break.`;

export const coastEvidence: SpotEvidence[] = [...UPGRADED_ROWS, ...COAST_ROWS].map(([id, name, region, type, lat, lon, seaward, timeZone, country]) => {
  const m = MARINE_POINT_OVERRIDES[id] ?? marinePoint(lat, lon, seaward);   // an explicit sea point where the default one is on land (marinePoints.ts)
  return {...common, ...(timeZone ? {timeZone} : {}), ...(country ? {country} : {}), sources: [], hazards: null, id, name, region, location: `${name} (approximate)`, latitude: lat, longitude: lon,
    marineLatitude: m.lat, marineLongitude: m.lon, queryNote: noteFor(kmBetween(lat, lon, m.lat, m.lon), id in MARINE_POINT_OVERRIDES), breakType: type};
});

/** True when the San Francisco tide station (9414290) is a fair regional reference (within ~70 km). */
export const nearSanFrancisco = (lat: number, lon: number) => Math.hypot(lat - 37.806, (lon + 122.466) * Math.cos((37.8 * Math.PI) / 180)) < 0.65;
